import{_ as t,o as n,c as a,ai as e}from"./chunks/framework.Ba-VnP44.js";const h=JSON.parse('{"title":"第一层 · AI 工程基础","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/01-foundation.md","filePath":"ai/productivity/dev-spec/01-foundation.md"}'),i={name:"ai/productivity/dev-spec/01-foundation.md"};function r(p,s,l,d,o,c){return n(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="第一层-·-ai-工程基础" tabindex="-1">第一层 · AI 工程基础 <a class="header-anchor" href="#第一层-·-ai-工程基础" aria-label="Permalink to “第一层 · AI 工程基础”">​</a></h1><blockquote><p>让 AI 正确工作。这一层是底座：把项目信息、规则、技能、分工、工具、自动化检查配置一次，长期复用，不用每次对话从头交代。</p></blockquote><h2 id="快速索引" tabindex="-1">快速索引 <a class="header-anchor" href="#快速索引" aria-label="Permalink to “快速索引”">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>解决什么</th><th>核心产物</th></tr></thead><tbody><tr><td>Project Context</td><td>AI 怎么拿到准确的项目信息</td><td>分层扫描的项目资料</td></tr><tr><td>Rules</td><td>AI 怎么遵守项目约束</td><td>一份可验证的规则文件</td></tr><tr><td>Skills</td><td>重复做法怎么固化</td><td>可调用的技能</td></tr><tr><td>Agents</td><td>谁来做什么、权限到哪</td><td>角色与文件所有权</td></tr><tr><td>MCP / Tools</td><td>怎么安全连接仓库外能力</td><td>工具能力边界清单</td></tr><tr><td>Hooks / Scripts</td><td>哪些检查不该靠人记</td><td>自动化检查脚本</td></tr></tbody></table><h2 id="_1-project-context-·-项目上下文" tabindex="-1">1. Project Context · 项目上下文 <a class="header-anchor" href="#_1-project-context-·-项目上下文" aria-label="Permalink to “1. Project Context · 项目上下文”">​</a></h2><p><strong>解决</strong>：反复解释项目背景；AI 全仓扫描把上下文占满；靠命名猜业务规则。</p><p><strong>四层收敛</strong>——由外到内，能停就停：</p><table tabindex="0"><thead><tr><th>层次</th><th>产出</th><th>能停的条件</th></tr></thead><tbody><tr><td>项目地图</td><td>模块清单 + 入口 + 构建方式</td><td>能说出「项目由哪几块组成」</td></tr><tr><td>模块地图</td><td>本次任务涉及的目录</td><td>能指出「改动落在哪个包」</td></tr><tr><td>调用链</td><td>入口 → 服务 → 数据完整路径</td><td>能画出「请求经过哪几层」</td></tr><tr><td>相关文件</td><td>待读待改清单（含受影响但不改的）</td><td>每个文件都说得出为何关心</td></tr></tbody></table><p>跳过 <code>node_modules/</code>、<code>target/</code>、<code>dist/</code>、<code>.git/</code> 等依赖和生成目录。调用链要覆盖异步任务、消息消费、配置开关、动态 SQL，追到数据落点和事务边界才算完。</p><p><strong>长期保存 vs 按任务提供</strong>：</p><table tabindex="0"><thead><tr><th>信息</th><th>放哪里</th></tr></thead><tbody><tr><td>能验证、反复用到的事实（技术栈、模块、命令、字段含义、历史决策）</td><td>项目资料（README / docs）</td></tr><tr><td>本次才有的（目标、相关文件、验收）</td><td>任务描述</td></tr><tr><td>踩过的坑</td><td>known-issues</td></tr><tr><td>推测、查不到的</td><td>待确认清单</td></tr></tbody></table><p>结论标状态：<strong>已确认</strong>（有证据）/ <strong>待确认</strong> / <strong>人工补充</strong>。不写「应该是 / 一般是」，gotchas 由人写。</p><blockquote><p>提示词 · 项目地图</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>只读分析，不修改文件，不提改进建议。跳过 node_modules、target、dist、.git、依赖和生成目录。</span></span>
<span class="line"><span>优先读构建文件、README、启动入口、前端入口、配置、目录结构，不逐个文件通读。</span></span>
<span class="line"><span>输出：1 技术栈 2 模块清单（模块→职责→入口）3 入口清单 4 目录概览 5 构建/启动/测试命令（附来源）6 配置文件清单 7 外部依赖 8 未覆盖范围。</span></span>
<span class="line"><span>结论带证据路径，推断放进「待确认」。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><blockquote><p>提示词 · 调用链</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>只读分析，从入口追到数据落点，不要停。必须覆盖同步调用、异步任务、消息消费、配置开关、动态 SQL。</span></span>
<span class="line"><span>每步给「文件路径:行号」和方法名；找出事务边界和异常处理；指出读写的表；找不到的标「未找到」。</span></span>
<span class="line"><span>输出：链路总览 / 逐层明细 / 涉及的表 / 事务与异常 / 隐藏路径 / 最易出问题的几处。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>检查点</strong>：五问能答上——改哪几个文件、谁受影响、涉及哪张表哪个接口、现有实现为什么这样、哪些地方不能碰。两条答不上就补，别带缺口改代码。</p><h2 id="_2-rules-·-项目规则" tabindex="-1">2. Rules · 项目规则 <a class="header-anchor" href="#_2-rules-·-项目规则" aria-label="Permalink to “2. Rules · 项目规则”">​</a></h2><p><strong>解决</strong>：每次对话重复交代约束；AI 命名分层不一致；口头禁令换个会话就忘。</p><p><strong>写什么</strong>：技术栈与版本、构建测试命令、命名分层、禁改目录、安全红线、跨任务成立的业务约束。 <strong>不写什么</strong>：本次任务、完整业务流程、分阶段步骤、「尽量 / 建议」这类无法验证的软规则。</p><p><strong>四条原则</strong>：可验证（能说清怎么算违反）· 用「必须 / 禁止」· 禁止项配反例 · 全局控制在几十行内。例外写明「谁确认、记在哪」。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># &lt;规则名&gt; · &lt;适用范围&gt;</span></span>
<span class="line"><span>## 必须遵守</span></span>
<span class="line"><span>| 编号 | 规则 | 验证方式 |</span></span>
<span class="line"><span>| C01 |      | &lt;命令或 diff 特征&gt; |</span></span>
<span class="line"><span>## 明确禁止</span></span>
<span class="line"><span>| 编号 | 禁止项 | 反例 | 验证方式 |</span></span>
<span class="line"><span>| P01 |        |      |          |</span></span>
<span class="line"><span>## 例外与审批</span></span>
<span class="line"><span>- 需要例外时由 &lt;角色&gt; 确认，记在 &lt;位置&gt;。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><blockquote><p>提示词 · 把约定整理成规则</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>把下面的项目约定整理成规则草稿，本轮只输出草稿，不写文件。</span></span>
<span class="line"><span>只保留跨任务成立、能验证的约束；每条用「必须/禁止」并配验证方式；禁止项配反例；删掉无法验证的软规则；写明适用范围和例外审批。</span></span>
<span class="line"><span>输出：规则草稿 + 被删内容及原因。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>检查点</strong>：没有任务措辞、没有软规则、每条可验证、AI 新会话能直接读到。</p><h2 id="_3-skills-·-专业技能" tabindex="-1">3. Skills · 专业技能 <a class="header-anchor" href="#_3-skills-·-专业技能" aria-label="Permalink to “3. Skills · 专业技能”">​</a></h2><p><strong>解决</strong>：同类操作每次重讲步骤；好做法只活在某次对话；把一次性绕法固化成垃圾。</p><p><strong>何时建</strong>（同时满足）：反复出现 · 有稳定步骤和检查点 · 至少两处验证有效。只做一两次的先留在交付报告。</p><p><strong>写什么</strong>：适用场景、前置条件、带检查点的步骤、失败处理、复用记录。 <strong>不写什么</strong>：具体表名/客户名/业务字段、一次性绕法、未验证的做法、完整业务流程。</p><blockquote><p>提示词 · 固化一个成功做法</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>先回答三问：还会再出现吗？不固化代价是什么？有没有第二处能验证？任一答不上就写「暂不固化，留在交付报告」。</span></span>
<span class="line"><span>三条都成立才产出技能草稿：适用场景 / 不适用 / 前置条件 / 带检查点的步骤 / 失败处理表 / 复用记录表。</span></span>
<span class="line"><span>只写「怎么做」的通用方法，不要写具体表名、客户名、业务字段。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>检查点</strong>：至少两处验证、步骤有检查点、没有业务字段污染、有复用记录。技能是资产不是垃圾桶，宁精勿滥。</p><h2 id="_4-agents-·-智能体协作" tabindex="-1">4. Agents · 智能体协作 <a class="header-anchor" href="#_4-agents-·-智能体协作" aria-label="Permalink to “4. Agents · 智能体协作”">​</a></h2><p><strong>解决</strong>：多开窗口互相覆盖；AI 既当运动员又当裁判；一句话派活导致理解不一。</p><p><strong>何时拆</strong>：前后端按冻结契约并行、互不冲突的模块、执行+审查、并行检索。<strong>不要拆</strong>：小任务、强耦合、需求没冻结、同一文件多人改。</p><p><strong>三条硬边界</strong>：</p><ol><li><strong>文件所有权</strong>：每个 Agent 明确负责哪些文件、哪些只读，同一文件不同时改。</li><li><strong>契约先冻结</strong>：接口、数据结构、字段名先定稿再并行；契约一变所有人重读。</li><li><strong>审查者不判定通过</strong>：执行/审查/规划分开，审查只输出问题清单，最终由人判定。</li></ol><p>派活要给同一份完整输入：任务 + 修改范围 + 不做项 + 验收标准。</p><blockquote><p>提示词 · 多 Agent 分工</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>先给分工方案，不要开始改代码。任务：&lt;一句话&gt;。冻结的契约：&lt;接口/结构/字段，或「需先冻结」&gt;。</span></span>
<span class="line"><span>要求：1 按文件所有权划分，同一文件不同时改 2 契约没冻结就只做契约设计 3 每个 Agent 收到同一份任务/范围/不做项/验收 4 含执行者和审查者，审查只报问题不判通过 5 说明结果如何收拢和最终谁验收。</span></span>
<span class="line"><span>先输出分工表和风险点，等我确认再启动。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>检查点</strong>：文件所有权无重叠、契约已冻结、没有一句话派活、审查者没自行宣布通过。</p><h2 id="_5-mcp-tools-·-工具与外部能力" tabindex="-1">5. MCP / Tools · 工具与外部能力 <a class="header-anchor" href="#_5-mcp-tools-·-工具与外部能力" aria-label="Permalink to “5. MCP / Tools · 工具与外部能力”">​</a></h2><p><strong>解决</strong>：接一堆用不上的工具；权限过大能读生产；工具挂了整个流程卡死。</p><p><strong>接入三问</strong>（有一条答不上就不接）：</p><table tabindex="0"><thead><tr><th>检查</th><th>要回答</th></tr></thead><tbody><tr><td>必要性</td><td>仓库内拿不到、又确实必须的吗？有更简单的替代吗？</td></tr><tr><td>边界</td><td>开放什么权限？只读还是可写？能碰生产吗？</td></tr><tr><td>降级</td><td>不可用时怎么办？有替代检查或手动方案吗？</td></tr></tbody></table><p><strong>权限最小化</strong>：能只读不写、能连测试库不连生产、能限定目录不开放全盘；删除/写入/发送动作明确需要人确认。记录能力清单（接了什么、开放什么、谁配置、怎么降级）。</p><blockquote><p>提示词 · 评估是否接入</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>三问评估这个工具：必要性（仓库内是否拿不到且必须）、边界（权限/范围/是否碰生产）、降级（不可用怎么办）。</span></span>
<span class="line"><span>给权限最小化建议、哪些动作需人确认、结论（建议/暂缓/不建议）及理由。答不上的标「待确认」，不要替我假设。本轮只评估不配置。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>检查点</strong>：三问都有答案、权限最小、有降级、能查到能力清单。</p><h2 id="_6-hooks-scripts-·-自动化执行" tabindex="-1">6. Hooks / Scripts · 自动化执行 <a class="header-anchor" href="#_6-hooks-scripts-·-自动化执行" aria-label="Permalink to “6. Hooks / Scripts · 自动化执行”">​</a></h2><p><strong>解决</strong>：靠提示词提醒跑测试偶尔忘；红线只口头说过；Hook 装太多误报被忽略。</p><p><strong>什么交给脚本</strong>（两条都满足）：漏了就出事 + 能明确判定。典型：构建、类型检查、单测、密钥扫描、禁改区 diff、遗留文件清理、lint。<strong>需要业务判断的不交给脚本</strong>。</p><p><strong>先写独立脚本，稳定后再挂到 Hook；不要一上来挂一堆。</strong> 检查要快、准（少误报）、报错可解释、跳过有留痕。</p><blockquote><p>提示词 · 把重复检查固化成脚本</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>本轮只出方案不写代码。对每项检查判断：是否「漏了就出事且能明确判定」（否则留人工）。</span></span>
<span class="line"><span>给出脚本要做的事、输入输出、失败报错（说清怎么改）、建议触发时机（显式/提交前 Hook）。</span></span>
<span class="line"><span>只把最关键最稳定的挂 Hook，慢检查单独跑。输出：可脚本化清单 + 方案 + 建议挂 Hook 的最小集合。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>检查点</strong>：自动化的都满足两条件、需要判断的留人工、Hook 最小且无误报、跳过有留痕。</p><hr><p>这一层是底座。配置好后，第二层每次开发直接调用；第三层的确定性检查靠本层脚本落地。回到 <a href="/my-vitepress-site/ai/productivity/dev-spec/">总览</a> · 下一层 <a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle.html">第二层 · 软件开发生命周期</a>。</p>`,58)])])}const g=t(i,[["render",r]]);export{h as __pageData,g as default};
